$(window).on("scroll", function () { if ($(window).scrollTop() > 50) {
$(".header").addClass("active");
} else {
//remove the background property so it comes transparent again (defined in your css)
$(".header").removeClass("active");
}
});
var input = document.getElementById("txtEmail");
input.focus();
input.addEventListener("keyup", function (event) { event.preventDefault();
if (event.keyCode === 13) { document.getElementById("btnSubscribe").click();
}
});
$("#btnSubscribe").click(function () { var email = $("#txtEmail").val();
debugger;
var vald = validateEmail(email);
if (!vald) { alert('Please enter a valid e-mail address');
return;
}
$.post("Newsletters/Subscribe?email=" + email + "&name=" + email, function (data, status) {
$("#ctrlSubscribe").hide();
if (data == "Reg") {
$("#msgSubscribe").text("Thank you for subscribing our newsletter.");
} else if (data == "Exists") {
$("#msgSubscribe").text("Email already exists in subscription list.");
}
$("#msgSubscribe").show();
});
});
function validateEmail(email) {
var re = /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
return re.test(email);
}
